  overflow-x: auto;
}

.market-item {
  flex: 1;
  min-width: 150px;
  background: var(--bg-secondary);
  padding: var(--space-md);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.market-item:hover { background: var(--bg-hover); }

.market-item .label {
  font-size: 0.7rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 2px;
}

.market-item .ticker {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--text-secondary);
  margin-bottom: 4px;
}

.market-item .value {
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 600;
}

.market-item .chg {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  margin-top: 2px;
}

/* --- Grids --- */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-lg); }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-lg); }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-lg); }

/* --- Hero --- */
.hero {
  padding: var(--space-3xl) 0 var(--space-2xl);
  text-align: center;
  background: linear-gradient(180deg, oklch(18% 0.02 260) 0%, var(--bg-primary) 100%);
  margin-top: var(--nav-height);
}

.hero h1 {
  font-size: 3rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  max-width: 800px;
  margin: 0 auto var(--space-md);
  line-height: 1.1;
  background: linear-gradient(135deg, var(--text-primary) 0%, oklch(80% 0.05 265) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 1.1rem;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto var(--space-xl);
  line-height: 1.6;
}

.hero-actions {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
}

/* --- Section Header --- */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
}

.section-header h2 {
  font-size: 1.25rem;
  font-weight: 700;
}

/* --- Stats Banner --- */
.stats-banner {
  display: flex;
  gap: var(--space-lg);
  justify-content: center;
  padding: var(--space-2xl) 0;
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.stat-item {
  text-align: center;
}

.stat-item .stat-value {
  font-size: 2rem;
  font-weight: 800;
  font-family: var(--font-mono);
  color: var(--accent);
}

.stat-item .stat-label {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-top: var(--space-xs);
}

/* --- Chart Workspace --- */
.chart-workspace {
  display: grid;
  grid-template-columns: 260px 1fr;
  margin-top: var(--nav-height);
  height: calc(100vh - var(--nav-height));
}

/* Watchlist Sidebar */
.watchlist-sidebar {
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-subtle);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

.watchlist-header {
  padding: var(--space-md);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.watchlist-header h3 {
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
}

.watchlist-category {
  border-bottom: 1px solid var(--border-subtle);
}

.watchlist-cat-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  cursor: pointer;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  transition: background var(--transition-fast);
  user-select: none;
}

.watchlist-cat-header:hover { background: var(--bg-hover); }

.watchlist-cat-header .arrow {
  font-size: 0.6rem;
  transition: transform var(--transition-fast);
}

.watchlist-items {
  display: none;
}

.watchlist-category.open .watchlist-items {
  display: block;
}

.watchlist-category.open .arrow {
  transform: rotate(90deg);
}

.watchlist-row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  padding: 6px var(--space-md);
  font-size: 0.8125rem;
  cursor: pointer;
  transition: background var(--transition-fast);
}

.watchlist-row:hover { background: var(--bg-hover); }
.watchlist-row.active { background: var(--accent-muted); }

.watchlist-row .sym {
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 0.75rem;
}

.watchlist-row .last {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  text-align: right;
  margin-right: 6px;
}

.watchlist-row .chg-pct {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  text-align: right;
  padding: 1px 6px;
  border-radius: 3px;
  min-width: 60px;
  text-align: center;
}

/* Chart Main Area */
.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.chart-toolbar {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) var(--space-md);
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-subtle);
  flex-wrap: wrap;
}

.toolbar-divider {
  width: 1px;
  height: 20px;
  background: var(--border-default);
  margin: 0 var(--space-xs);
}

.chart-container {
  flex: 1;
  position: relative;
  background: var(--bg-primary);
  min-height: 300px;
}

.chart-container canvas {
  width: 100%;
  height: 100%;
}

/* Stock Detail Panel */
.detail-panel {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-subtle);
  padding: var(--space-lg);
}

.detail-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
}

.detail-ticker {
  display: flex;
  align-items: baseline;
  gap: var(--space-md);
}

.detail-ticker h2 {
  font-size: 1.5rem;
  font-family: var(--font-mono);
}

.detail-ticker .company {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

.detail-ticker .exchange {
  color: var(--text-muted);
  font-size: 0.75rem;
}

.detail-price {
  font-family: var(--font-mono);
  font-size: 2rem;
  font-weight: 700;
}

.detail-metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: var(--space-md);
  margin-top: var(--space-lg);
}

.detail-metric {
  background: var(--bg-tertiary);
  padding: var(--space-md);
  border-radius: var(--radius-md);
}

.detail-metric .label {
  font-size: 0.6875rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}

.detail-metric .val {
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 600;
}

/* KPI Cards */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-sm);
}

.kpi-card {
  background: var(--bg-tertiary);
  padding: var(--space-md);
  border-radius: var(--radius-md);
}

.kpi-label {
  font-size: 0.6875rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.kpi-value {
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 600;
  margin-top: 4px;
}

/* --- Idea Cards --- */
.idea-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition-fast), transform var(--transition-fast);
}

.idea-card:hover {
  border-color: var(--border-default);
  transform: translateY(-1px);
}

.idea-card-header {
  padding: var(--space-md) var(--space-lg);
  display: flex;
  align-items: center;
  gap: var(--space-md);
  border-bottom: 1px solid var(--border-subtle);
}

.idea-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--accent-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.8rem;
  color: var(--accent);
}

.idea-user {
  font-weight: 600;
  font-size: 0.875rem;
}

.idea-meta {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-left: auto;
}

.idea-card-body {
  padding: var(--space-lg);
}

.idea-card-body h4 {
  font-size: 1rem;
  margin-bottom: var(--space-sm);
}

.idea-card-body p {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.idea-card-body .chart-preview {
  background: var(--bg-tertiary);
  border-radius: var(--radius-md);
  height: 180px;
  margin: var(--space-md) 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.idea-tags {
  display: flex;
  gap: var(--space-xs);
  flex-wrap: wrap;
  margin-top: var(--space-md);
}

.idea-tag {
  padding: 2px 8px;
  border-radius: 3px;
  font-size: 0.6875rem;
  background: var(--bg-tertiary);
  color: var(--text-secondary);
}

.idea-card-footer {
  padding: var(--space-md) var(--space-lg);
  border-top: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.idea-stat {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* --- Broker Cards --- */
.broker-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  transition: border-color var(--transition-fast);
}

.broker-card:hover { border-color: var(--border-default); }

.broker-card-header {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  margin-bottom: var(--space-md);
}

.broker-logo {
  width: 48px;
  height: 48px;
  background: var(--bg-tertiary);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 0.8rem;
  color: var(--accent);
}

.broker-name {
  font-size: 1.1rem;
  font-weight: 700;
}

.broker-tier {
  font-size: 0.6875rem;
  padding: 2px 8px;
  border-radius: 3px;
  font-weight: 600;
}

.tier-platinum {
  background: oklch(60% 0.1 265 / 0.2);
  color: oklch(70% 0.15 265);
}

.tier-gold {
  background: oklch(75% 0.15 85 / 0.2);
  color: oklch(80% 0.15 85);
}

.broker-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-sm);
  margin-bottom: var(--space-md);
}

.broker-stat {
  text-align: center;
}

.broker-stat .val {
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 0.9375rem;
}

.broker-stat .lbl {
  font-size: 0.6875rem;
  color: var(--text-muted);
  margin-top: 2px;
}

.broker-promo {
  padding: var(--space-sm) var(--space-md);
  background: var(--accent-muted);
  border-radius: var(--radius-sm);
  font-size: 0.8125rem;
  color: var(--accent);
  text-align: center;
  margin-bottom: var(--space-md);
}

.broker-actions {
  display: flex;
  gap: var(--space-sm);
}

/* --- Pagination --- */
.pagination {
  display: flex;
  justify-content: center;
  gap: var(--space-xs);
  margin-top: var(--space-xl);
}

.pagination button {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  color: var(--text-secondary);
  font-weight: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}

.pagination button:hover { background: var(--bg-hover); color: var(--text-primary); }
.pagination button.active {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

/* --- Footer --- */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-subtle);
  padding: var(--space-2xl) 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: var(--space-xl);
}

.footer-col h4 {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: var(--space-md);
}

.footer-col a {
  display: block;
  padding: 4px 0;
  font-size: 0.8125rem;
  color: var(--text-secondary);
}

.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  margin-top: var(--space-xl);
  padding-top: var(--space-lg);
  border-top: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* --- Mini Charts / Sparklines --- */
.sparkline {
  display: flex;
  align-items: flex-end;
  gap: 1px;
  height: 32px;
}

.sparkline .bar {
  flex: 1;
  border-radius: 1px 1px 0 0;
  transition: height var(--transition-base);
}

/* --- Candlestick mini --- */
.mini-candle {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 32px;
}

/* --- News / Story Cards --- */
.story-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition-fast);
}

.story-card:hover { border-color: var(--border-default); }

.story-card-body {
  padding: var(--space-lg);
}

.story-card-body h4 {
  font-size: 0.9375rem;
  margin-bottom: var(--space-sm);
  line-height: 1.4;
}

.story-card-body p {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.story-source {
  font-size: 0.75rem;
  color: var(--text-muted);
  margin-top: var(--space-md);
}

/* --- Indicators List --- */
.indicator-item {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md);
  background: var(--bg-tertiary);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-sm);
}

.indicator-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: var(--accent-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  color: var(--accent);
}

.indicator-info h4 {
  font-size: 0.875rem;
  margin-bottom: 2px;
}

.indicator-info p {
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* --- Earnings Calendar --- */
.earnings-row {
  display: grid;
  grid-template-columns: 160px 1fr auto auto;
  align-items: center;
  padding: var(--space-sm) var(--space-md);
  border-bottom: 1px solid var(--border-subtle);
  font-size: 0.875rem;
}

.earnings-row:hover { background: var(--bg-hover); }

.earnings-date {
  color: var(--text-secondary);
  font-size: 0.8125rem;
}

.earnings-company {
  font-weight: 600;
}

/* --- Gainers/Losers --- */
.movers-list {
  display: grid;
  gap: 2px;
}

.mover-item {
  display: flex;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  background: var(--bg-tertiary);
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
}

.mover-change {
  font-family: var(--font-mono);
  font-weight: 600;
}

/* --- Crypto Stats --- */
.crypto-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
}

.crypto-stat {
  background: var(--bg-secondary);
  padding: var(--space-lg);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-subtle);
}

.crypto-stat .label {
  font-size: 0.75rem;
  color: var(--text-muted);
  text-transform: uppercase;
}

.crypto-stat .value {
  font-family: var(--font-mono);
  font-size: 1.5rem;
  font-weight: 700;
  margin-top: var(--space-xs);
}

.crypto-stat .change {
  font-family: var(--font-mono);
  font-size: 0.875rem;
  margin-top: 4px;
}

/* --- Asset Class Tabs (large) --- */
.asset-tabs {
  display: flex;
  gap: var(--space-sm);
  overflow-x: auto;
  padding-bottom: var(--space-xs);
}

.asset-tab {
  padding: var(--space-sm) var(--space-lg);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  cursor: pointer;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.asset-tab:hover { color: var(--text-primary); border-color: var(--border-default); }
.asset-tab.active {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

/* --- Bond Yield Curve --- */
.yield-bars {
  display: flex;
  align-items: flex-end;
  gap: var(--space-md);
  height: 120px;
  padding: var(--space-md) 0;
}

.yield-bar-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-xs);
}

.yield-bar {
  width: 100%;
  max-width: 40px;
  border-radius: 4px 4px 0 0;
  background: var(--accent);
  transition: height var(--transition-slow);
}

.yield-bar-label {
  font-size: 0.625rem;
  color: var(--text-muted);
}

.yield-bar-value {
  font-size: 0.6875rem;
  font-family: var(--font-mono);
}

/* --- Tooltip --- */
.tooltip {
  position: absolute;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: var(--space-sm) var(--space-md);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  pointer-events: none;
  z-index: 200;
  box-shadow: var(--shadow-md);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .chart-workspace {
    grid-template-columns: 1fr;
  }
  .watchlist-sidebar { display: none; }
  .watchlist-sidebar.mobile-visible { display: flex; position: fixed; top: var(--nav-height); left: 0; bottom: 0; width: 260px; z-index: 50; }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .crypto-stats { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  html { font-size: 13px; }
  .nav-links { display: none; }
  .nav-menu-btn { display: block; }
  h1 { font-size: 1.8rem; }
  .hero h1 { font-size: 2rem; }
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .crypto-stats { grid-template-columns: 1fr; }
  .market-bar { flex-wrap: wrap; }
  .market-item { min-width: 120px; flex: 0 0 auto; }
  .stats-banner { flex-direction: column; gap: var(--space-lg); }
  .broker-stats { grid-template-columns: repeat(3, 1fr); }
  .container { padding: 0 var(--space-md); }
  .detail-metrics { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 480px) {
  .hero-actions { flex-direction: column; align-items: center; }
  .detail-metrics { grid-template-columns: 1fr; }
}

/* --- Utilities --- */
.mt-sm { margin-top: var(--space-sm); }
.mt-md { margin-top: var(--space-md); }
.mt-lg { margin-top: var(--space-lg); }
.mt-xl { margin-top: var(--space-xl); }
.mb-sm { margin-bottom: var(--space-sm); }
.mb-md { margin-bottom: var(--space-md); }
.mb-lg { margin-bottom: var(--space-lg); }
.mb-xl { margin-bottom: var(--space-xl); }
.text-right { text-align: right; }
.text-center { text-align: center; }
.hidden { display: none; }
.flex { display: flex; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-sm { gap: var(--space-sm); }
.gap-md { gap: var(--space-md); }
.gap-lg { gap: var(--space-lg); }
.w-full { width: 100%; }
